@media (max-width: 767px) {
  body { flex-direction: column; padding-bottom: calc(100px + env(safe-area-inset-bottom)); }
  .sidebar { display: none !important; }
  .mobile-bottom-nav { display: flex; position: fixed; bottom: 0px; left: 0px; right: 0px; height: auto; min-height: 60px; background: var(--strategy-sidebar-bg); border-top: 1px solid var(--strategy-border); padding-top: 4px; padding-right: 0px; padding-left: 0px; padding-bottom: calc(12px + env(safe-area-inset-bottom)); justify-content: space-around; align-items: center; z-index: 9999999; box-shadow: rgba(0, 0, 0, 0.1) 0px -2px 8px; }
  .mobile-tab-item { display: flex; flex-direction: column; align-items: center; justify-content: center; flex: 1 1 0%; cursor: pointer; padding: 6px 4px; transition: 0.2s; color: var(--strategy-text-muted); -webkit-tap-highlight-color: transparent; position: relative; }
  .mobile-tab-item.active { color: var(--strategy-primary); }
  .mobile-tab-item.active::before { content: ""; position: absolute; top: 0px; left: 50%; transform: translateX(-50%); width: 24px; height: 3px; background: var(--strategy-primary); border-radius: 0px 0px 3px 3px; }
  .mobile-tab-icon { width: 24px; height: 24px; margin-bottom: 2px; transition: 0.2s; }
  .mobile-tab-item.active .mobile-tab-icon { transform: scale(1.1); }
  .mobile-tab-text { font-size: 11px; font-weight: 500; transition: 0.2s; }
  .mobile-tab-item.active .mobile-tab-text { font-weight: 600; }
  .mobile-tab-item:active { background: var(--strategy-hover-bg); border-radius: 8px; }
  .content-wrapper { width: 100%; padding: 12px !important; overflow: hidden auto !important; }
  body #indicatorLibraryContent, body #kolStrategyContent { overflow: visible; height: auto; max-height: none; }
  body .scrollable-content { overflow: visible !important; padding: 0px !important; height: auto !important; min-height: auto !important; flex: 0 0 auto !important; }
  body .fixed-header { position: static !important; padding: 0px !important; }
  .category-grid, .main-container { gap: 10px; }
  .category-tab { padding: 10px 16px; font-size: 13px; }
  .strategy-card { padding: 10px !important; border-radius: 8px !important; margin-bottom: 0px !important; }
  .strategy-header { margin-bottom: 8px !important; gap: 6px !important; }
  .strategy-title { font-size: 14px !important; height: auto !important; -webkit-line-clamp: 1 !important; line-height: 1.3 !important; }
  .status-badge { font-size: 9px !important; padding: 2px 6px !important; border-radius: 3px !important; }
  .action-buttons .btn { padding: 5px 10px !important; font-size: 11px !important; border-radius: 5px !important; }
  .action-buttons .icon { width: 12px !important; height: 12px !important; }
  .performance-section { margin: 8px 0px !important; gap: 8px !important; display: flex !important; align-items: flex-start !important; }
  .performance-info { flex: 0 0 auto !important; min-width: 90px !important; max-width: 110px !important; }
  .performance-label { font-size: 10px !important; margin-bottom: 2px !important; line-height: 1.3 !important; }
  .performance-value { font-size: 16px !important; line-height: 1.2 !important; }
  .info-icon { width: 11px !important; height: 11px !important; }
  .chart-placeholder { height: 50px !important; min-height: 50px !important; max-height: 50px !important; flex: 1 1 0% !important; width: 0px !important; display: flex !important; justify-content: flex-end !important; }
  .chart-canvas { height: 50px !important; max-height: 50px !important; width: 50% !important; }
  .stats-grid { gap: 5px 8px !important; margin-top: 6px !important; }
  .stat-item { padding: 6px 8px !important; border-radius: 4px !important; }
  .stat-label { font-size: 10px !important; margin-bottom: 2px !important; }
  .stat-value { font-size: 11px !important; line-height: 1.3 !important; }
  .author-section { gap: 6px !important; margin-top: 6px !important; padding-top: 6px !important; border-top-width: 1px !important; }
  .author-section img { width: 20px !important; height: 20px !important; }
  .author-name { font-size: 11px !important; }
  .social-stat { font-size: 10px !important; gap: 3px !important; }
  .social-stat .icon { width: 11px !important; height: 11px !important; }
  .btn { height: auto !important; }
  .btn-buy, .btn-share, .btn-use { padding: 5px 10px !important; font-size: 11px !important; }
}

@media (max-width: 480px) {
  .content-wrapper { padding: 8px !important; }
  .category-tab { padding: 7px 12px !important; font-size: 12px !important; }
  .strategy-card { padding: 8px !important; }
  .strategy-title { font-size: 13px !important; }
  .performance-value { font-size: 15px !important; }
  .performance-label { font-size: 9px !important; }
  .performance-info { min-width: 85px !important; max-width: 105px !important; }
  .chart-placeholder { height: 45px !important; min-height: 45px !important; max-height: 45px !important; flex: 1 1 0% !important; width: 0px !important; }
  .chart-canvas { height: 45px !important; max-height: 45px !important; width: 50% !important; }
  .stat-label { font-size: 9px !important; }
  .stat-value { font-size: 10px !important; }
}

@media (max-width: 768px) {
  body { flex-direction: column; padding-top: 0px; height: auto; overflow: visible; min-height: 100vh; }
  .sidebar { display: none; }
  .content-wrapper { padding: 12px; width: 100%; height: auto; overflow-y: visible; }
  .page-header-top { flex-direction: column; align-items: stretch; gap: 12px; }
  .search-controls { order: -1; width: 100%; display: flex; align-items: center; gap: 8px; position: relative; }
  .sort-toggle-btn { display: flex; padding: 8px 14px; border-radius: 12px; flex-shrink: 0; }
  .search-toggle-btn { display: none; }
  .search-input-wrapper { flex: 1 1 0%; min-width: 0px; display: flex; }
  .search-input-wrapper .search-input { width: 100%; border-radius: 12px; padding: 10px 44px 10px 14px; font-size: 14px; }
  .search-btn-inline { right: 4px; padding: 8px; border-radius: 8px; }
  .create-btn-text { display: inline; }
  .create-btn { margin-left: 0px; padding: 8px 14px; border-radius: 12px; box-shadow: rgba(59, 130, 246, 0.3) 0px 4px 12px; flex-shrink: 0; }
  .category-tabs-wrapper { overflow-x: auto; margin-bottom: 0px; scrollbar-width: none; }
  .category-tabs-wrapper::-webkit-scrollbar { display: none; }
  .category-tabs { display: flex; flex-wrap: nowrap; gap: 2px; min-width: min-content; justify-content: space-between; }
  .category-tab { white-space: nowrap; flex-shrink: 0; padding: 8px 4px; font-size: 13px; margin-right: 0px; cursor: pointer; user-select: none; -webkit-tap-highlight-color: transparent; }
  .sidebar-item { padding: 14px 20px; display: flex; flex-direction: column; }
  .sidebar-item-title { font-size: 14px; display: flex; align-items: center; }
  .sidebar-item-desc { font-size: 11px; margin-top: 4px; }
  .category-grid, .main-container { width: 100%; gap: 12px; grid-template-columns: 1fr !important; }
  .view-all-btn { padding: 8px 16px; font-size: 13px; touch-action: manipulation; -webkit-tap-highlight-color: transparent; }
  .action-btn, .primary-btn, .secondary-btn { min-height: 44px; touch-action: manipulation; -webkit-tap-highlight-color: transparent; }
  .category-tab, .sidebar-item, a, button { touch-action: manipulation; -webkit-tap-highlight-color: transparent; }
  .square-header-wrapper { flex-direction: column; align-items: stretch; gap: 16px; margin-bottom: 16px; }
  .square-title { font-size: 24px; }
  .square-subtitle { font-size: 13px; }
  .video-carousel-banner { height: 100px; width: 100%; max-width: 100%; }
  .video-carousel-controls { bottom: 10px; }
  .video-carousel-dot { width: 8px; height: 8px; }
  .video-carousel-dot.active { width: 24px; }
  .strategy-grid { grid-template-columns: 1fr; gap: 12px; }
}

@media (min-width: 769px) and (max-width: 1024px) {
  .sidebar { width: 200px; position: relative; left: 0px; }
  .sidebar-item { padding: 12px 16px; }
  .sidebar-item-title { font-size: 14px; }
  .content-wrapper { padding: 20px; margin-top: 0px; }
  .strategy-grid { grid-template-columns: repeat(2, 1fr); gap: 14px; }
}

@media (max-width: 768px) {
  .block-builder-wrapper { flex-direction: column !important; padding: 12px !important; }
  .block-library-panel { width: 100% !important; border-right-width: medium !important; border-right-style: none !important; border-right-color: currentcolor !important; flex: 1 1 0% !important; padding: 0px !important; background: 0px 0px !important; }
  .block-canvas-panel { display: none !important; }
  #blockSelectorModal .modal-container { width: 100% !important; height: 100% !important; max-height: 100% !important; border-radius: 0px !important; max-width: 100% !important; }
  #blockSelectorModal .modal-body { background: var(--strategy-bg-secondary); }
  .draggable-block.selected { background: rgba(255, 255, 255, 0.05); border-color: var(--block-color) !important; }
}

@media (max-width: 1024px) {
  .competition-main-content { grid-template-columns: 280px 1fr; gap: 16px; }
  .competition-stats { gap: 24px; }
  .stat-icon { font-size: 20px; }
  .stat-label { font-size: 12px; }
  .stat-value { font-size: 16px; }
}

@media (max-width: 768px) {
  .competition-header { padding: 16px; }
  .competition-stats { flex-direction: column; gap: 16px; align-items: flex-start; }
  .stat-item { width: 100%; justify-content: space-between; }
  .competition-main-content { display: flex; flex-direction: column; gap: 16px; height: auto; min-height: auto; }
  .competition-sidebar { height: auto; max-height: 350px; position: static; order: 2; }
  .competition-chart-area { height: 350px; width: 100%; position: static; order: 1; }
  .chart-header { flex-direction: row; align-items: center; gap: 12px; }
  .chart-controls { width: auto; }
  .chart-control-btn { padding: 4px 10px; font-size: 11px; }
  .competition-activities { padding: 12px 16px; }
  .activities-header { flex-direction: row; align-items: center; gap: 8px; }
  .trader-detail-content { width: 95%; max-height: 90vh; }
  .modal-header { padding: 16px; }
  .modal-body { padding: 16px; }
  .competition-detail-grid { grid-template-columns: 1fr; gap: 12px; }
  .positions-table { font-size: 11px; }
  .positions-table th, .positions-table td { padding: 8px 6px; }
}
